<?php namespace App\Http\Controllers\Api; class OpportunityController extends CrudController{protected string $model=\App\Models\Opportunity::class;protected array $rules=['company_id'=>'required|exists:companies,id','title'=>'required|string|max:255','external_id'=>'nullable|string|max:100','type'=>'nullable|string|max:150','potential_service'=>'nullable|string','potential_value'=>'nullable|numeric|min:0','status'=>'required|string|max:50','probability'=>'nullable|integer|min:0|max:100','score'=>'nullable|integer|min:0|max:100','next_step_at'=>'nullable|date','summary'=>'nullable|string','source_url'=>'nullable|string|max:500'];protected array $searchable=['title','status'];protected array $with=['company']; public function status(\Illuminate\Http\Request $r,int $id){$data=$r->validate(['status'=>'required|string|max:50']);$m=(new $this->model)->findOrFail($id);$m->update($data);return $m->fresh('company');}}
